type ListWashBatchesParams struct {
	TenantID   uuid.UUID
	FacilityID string
	MachineID  string
	Cycle      string
	States     []string
	FromTime   pgtype.Timestamptz
	ToTime     pgtype.Timestamptz
	PageOffset int32
	PageLimit  int32
}

func (q *Queries) ListWashBatches(ctx context.Context, arg ListWashBatchesParams) ([]LaundryWashBatch, error) {
	rows, err := q.db.Query(ctx, listWashBatches,
		arg.TenantID,
		arg.FacilityID,
		arg.MachineID,
		arg.Cycle,
		arg.States,
		arg.FromTime,
		arg.ToTime,
		arg.PageOffset,
		arg.PageLimit,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LaundryWashBatch{}
	for rows.Next() {
		var i LaundryWashBatch
		if err := rows.Scan(
			&i.BatchID,
			&i.TenantID,
			&i.Reference,
			&i.FacilityID,
			&i.MachineID,
			&i.Cycle,
			&i.Infected,
			&i.WeightG,
			&i.State,
			&i.Outcome,
			&i.PeakTemperatureC,
			&i.HoldMinutes,
			&i.RewashBatchID,
			&i.RewashOfBatchID,
			&i.StartedAt,
			&i.StartedBy,
			&i.CompletedAt,
			&i.CompletedBy,
			&i.CreatedAt,
			&i.CreatedBy,
			&i.Version,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

